-- db/schema.sql: the progress database after every migration, in creation order.
-- Generated by `npm run progress:schema` (scripts/progress-db/dump-schema.mjs). Do not edit it by hand.
-- The commentary is in db/migrations/*.sql, which is the source of truth; comments inside each
-- CREATE statement are kept here as SQLite stores them.

CREATE TABLE schema_migration (
  version    INTEGER PRIMARY KEY,
  name       TEXT NOT NULL,
  applied_at TEXT NOT NULL
) STRICT;

CREATE TABLE lesson (
  id          INTEGER PRIMARY KEY,                  -- the chapter number: lesson 07 -> 7
  slug        TEXT NOT NULL UNIQUE,                 -- 'creating-and-populating-a-database'
  title       TEXT NOT NULL,
  max_points  INTEGER NOT NULL CHECK (max_points > 0)  -- sum of its items (the kit uses 100)
) STRICT;

CREATE TABLE item (
  id          INTEGER PRIMARY KEY,
  lesson_id   INTEGER NOT NULL REFERENCES lesson(id),
  code        TEXT NOT NULL,                        -- 'cp3', 'lab2'
  kind        TEXT NOT NULL CHECK (kind IN ('checkpoint', 'lab')),  -- CHECK is the only guard here; no enum type
  ordinal     INTEGER NOT NULL CHECK (ordinal > 0),
  label       TEXT NOT NULL,                        -- 'Primary & foreign keys'
  max_points  INTEGER NOT NULL CHECK (max_points > 0),
  UNIQUE (lesson_id, code)                          -- a code names one item within its lesson only
) STRICT;

CREATE TABLE concept (
  id    INTEGER PRIMARY KEY,
  name  TEXT NOT NULL UNIQUE
) STRICT;

CREATE TABLE item_concept (
  item_id     INTEGER NOT NULL REFERENCES item(id)    ON DELETE CASCADE,
  concept_id  INTEGER NOT NULL REFERENCES concept(id) ON DELETE CASCADE,
  PRIMARY KEY (item_id, concept_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE session (
  id              INTEGER PRIMARY KEY,
  client_uid      TEXT NOT NULL UNIQUE,
  lesson_id       INTEGER NOT NULL REFERENCES lesson(id),
  started_at      TEXT NOT NULL,
  last_seen_at    TEXT NOT NULL,
  active_seconds  INTEGER NOT NULL DEFAULT 0 CHECK (active_seconds >= 0),
  CHECK (last_seen_at >= started_at)                -- text comparison is valid for this fixed format
) STRICT;

CREATE TABLE attempt (
  id             INTEGER PRIMARY KEY,
  client_uid     TEXT NOT NULL UNIQUE,              -- idempotency key from the browser
  session_id     INTEGER NOT NULL REFERENCES session(id),
  item_id        INTEGER NOT NULL REFERENCES item(id),
  attempt_no     INTEGER NOT NULL CHECK (attempt_no > 0),  -- 1, 2, 3 per item; the server computes it
  submitted_at   TEXT NOT NULL,
  score          REAL NOT NULL CHECK (score >= 0),
  max_points     INTEGER NOT NULL CHECK (max_points > 0),  -- snapshot: grading may change later
  skipped        INTEGER NOT NULL DEFAULT 0 CHECK (skipped IN (0, 1)),
  seconds_spent  INTEGER CHECK (seconds_spent >= 0),       -- active time on the slide; NULL if unknown
  answer_sql     TEXT,                                     -- labs only
  verdict        TEXT,                                     -- the grader's message for labs
  source         TEXT NOT NULL DEFAULT 'live' CHECK (source IN ('live', 'backfill')),
  CHECK (score <= max_points),
  UNIQUE (item_id, attempt_no)                       -- the same attempt number cannot repeat for an item
) STRICT;

CREATE TABLE attempt_part (
  attempt_id  INTEGER NOT NULL REFERENCES attempt(id) ON DELETE CASCADE,
  part_no     INTEGER NOT NULL CHECK (part_no > 0),
  score       REAL    NOT NULL CHECK (score >= 0),
  max_points  REAL    NOT NULL CHECK (max_points > 0),
  answer      TEXT CHECK (answer IS NULL OR json_valid(answer)),  -- NULL means skipped
  PRIMARY KEY (attempt_id, part_no),
  CHECK (score <= max_points)
) STRICT, WITHOUT ROWID;

CREATE TABLE lab_run (
  id          INTEGER PRIMARY KEY,
  session_id  INTEGER NOT NULL REFERENCES session(id),
  item_id     INTEGER NOT NULL REFERENCES item(id),
  ran_at      TEXT NOT NULL,
  sql         TEXT NOT NULL,
  error       TEXT                                  -- NULL means it ran; otherwise the Postgres message
) STRICT;

CREATE INDEX attempt_item_history ON attempt (item_id, submitted_at);

CREATE INDEX attempt_session      ON attempt (session_id);

CREATE INDEX lab_run_session      ON lab_run (session_id);

CREATE INDEX lab_run_item_time    ON lab_run (item_id, ran_at);

CREATE INDEX session_lesson_time  ON session (lesson_id, started_at);

CREATE INDEX item_concept_reverse ON item_concept (concept_id);

CREATE VIEW v_item_latest AS
WITH ranked AS (
  SELECT a.*, i.code, i.lesson_id,
         ROW_NUMBER() OVER (PARTITION BY a.item_id ORDER BY a.attempt_no DESC) AS rn
  FROM attempt a
  JOIN item i ON i.id = a.item_id
)
SELECT item_id, code, lesson_id,
       id AS attempt_id,
       attempt_no,
       score,
       max_points,
       ROUND(100.0 * score / max_points, 1) AS pct,
       submitted_at
FROM ranked
WHERE rn = 1;

CREATE VIEW v_lesson_summary AS
SELECT l.id AS lesson_id,
       l.title,
       (SELECT COUNT(*) FROM session s WHERE s.lesson_id = l.id)                  AS sessions,
       (SELECT COALESCE(SUM(s.active_seconds), 0) FROM session s WHERE s.lesson_id = l.id) AS active_seconds,
       (SELECT MIN(s.started_at)   FROM session s WHERE s.lesson_id = l.id)       AS first_studied,
       (SELECT MAX(s.last_seen_at) FROM session s WHERE s.lesson_id = l.id)       AS last_studied,
       (SELECT COALESCE(SUM(li.score), 0) FROM v_item_latest li WHERE li.lesson_id = l.id) AS total_score,
       ROUND(100.0 * (SELECT COALESCE(SUM(li.score), 0) FROM v_item_latest li WHERE li.lesson_id = l.id)
             / l.max_points, 1)                                                    AS total_pct
FROM lesson l;

CREATE VIEW v_item_weakness AS
SELECT i.id AS item_id,
       i.code,
       (SELECT COUNT(*) FROM attempt a WHERE a.item_id = i.id)                     AS attempts,
       (SELECT pct FROM v_item_latest l WHERE l.item_id = i.id)                    AS latest_pct,
       (SELECT MAX(ROUND(100.0 * a.score / a.max_points, 1)) FROM attempt a WHERE a.item_id = i.id) AS best_pct,
       (SELECT ROUND(1.0 * SUM(CASE WHEN a.score < a.max_points THEN 1 ELSE 0 END) / COUNT(*), 2)
          FROM attempt a WHERE a.item_id = i.id)                                   AS mistake_rate,
       (SELECT AVG(a.seconds_spent) FROM attempt a WHERE a.item_id = i.id)         AS avg_seconds,
       (SELECT COUNT(*) FROM lab_run r WHERE r.item_id = i.id AND r.error IS NOT NULL) AS errored_runs
FROM item i;

CREATE VIEW v_part_mistakes AS
SELECT i.code,
       a.item_id,
       a.id AS attempt_id,
       a.submitted_at,
       p.part_no,
       p.score,
       p.max_points,
       p.answer
FROM attempt_part p
JOIN attempt a ON a.id = p.attempt_id
JOIN item i    ON i.id = a.item_id
WHERE p.score < p.max_points
ORDER BY a.submitted_at DESC;

CREATE VIEW v_concept_weakness AS
SELECT c.id AS concept_id,
       c.name,
       COUNT(DISTINCT ic.item_id)                            AS items,
       COUNT(a.id)                                           AS attempts,
       ROUND(AVG(100.0 * a.score / a.max_points), 1)         AS avg_pct
FROM concept c
JOIN item_concept ic ON ic.concept_id = c.id
LEFT JOIN attempt a  ON a.item_id = ic.item_id
GROUP BY c.id, c.name;

CREATE VIEW v_review_queue AS
SELECT l.item_id,
       l.code,
       l.lesson_id,
       l.pct          AS latest_pct,
       l.submitted_at
FROM v_item_latest l
WHERE l.pct < 80
ORDER BY l.pct ASC, l.submitted_at ASC;
